/** Strategy card initiative numbers. */
export const STRATEGY_CARD_NUMBERS = [1, 2, 3, 4, 5, 6, 7, 8] as const;
export type StrategyCardNumber = (typeof STRATEGY_CARD_NUMBERS)[number];

/** Technology colour / kind (data/technologies `types`). */
export const TECH_TYPES = ["BIOTIC", "CYBERNETIC", "NONE", "PROPULSION", "UNITUPGRADE", "WARFARE"] as const;
export type TechType = (typeof TECH_TYPES)[number];

/** Agenda card type. */
export const AGENDA_TYPES = ["Directive", "Law"] as const;
export type AgendaType = (typeof AGENDA_TYPES)[number];

/** Leader card type. */
export const LEADER_TYPES = ["agent", "commander", "hero"] as const;
export type LeaderType = (typeof LEADER_TYPES)[number];

/** Planet trait / type as the data spells it. */
export const PLANET_TYPES = ["CULTURAL", "FACTION", "HAZARDOUS", "INDUSTRIAL", "MR", "SPACESTATION"] as const;
export type PlanetType = (typeof PLANET_TYPES)[number];

/** Game.phaseOfGame: every literal the engine passes to setPhaseOfGame ("" = a new game). Compare case-sensitively; older saves may hold other spellings (validate.ts logs them). */
export const PHASES = ["", "action", "agenda", "agendaEnd", "agendaVoting", "agendawaiting", "miltydraft", "playerSetup", "statusHomework", "statusScoring", "strategy"] as const;
export type Phase = (typeof PHASES)[number];

/** "<leaderId>", "<leaderId>:locked" or "<leaderId>:exhausted" (PlayerState.leaders). */
export type LeaderStatus = LeaderId | `${LeaderId}:locked` | `${LeaderId}:exhausted`;

// ---------------------------------------------------------------- lookups

const has = (list: readonly string[]) => {
  const set = new Set<string>(list);
  return (x: unknown): boolean => typeof x === "string" && set.has(x);
};
const COLOR_PN = new RegExp(`^(.+)_(${COLOR_PROMISSORY_NOTE_SUFFIXES.join("|")})$`);
const isColorName = has(COLORS);
const isFactionPn = has(FACTION_PROMISSORY_NOTE_IDS);

/** Membership tests per id family (string in, type guard out). */
export const is = {
  faction: has(FACTION_IDS) as (x: unknown) => x is FactionId,
  tech: has(TECH_IDS) as (x: unknown) => x is TechId,
  planet: has(PLANET_IDS) as (x: unknown) => x is PlanetId,
  tile: has(TILE_IDS) as (x: unknown) => x is TileId,
  unit: has(UNIT_IDS) as (x: unknown) => x is UnitId,
  actionCard: has(ACTION_CARD_IDS) as (x: unknown) => x is ActionCardId,
  agenda: has(AGENDA_IDS) as (x: unknown) => x is AgendaId,
  publicObjective: has(PUBLIC_OBJECTIVE_IDS) as (x: unknown) => x is PublicObjectiveId,
  secretObjective: has(SECRET_OBJECTIVE_IDS) as (x: unknown) => x is SecretObjectiveId,
  relic: has(RELIC_IDS) as (x: unknown) => x is RelicId,
  exploreCard: has(EXPLORE_CARD_IDS) as (x: unknown) => x is ExploreCardId,
  relicFragment: has(RELIC_FRAGMENT_IDS) as (x: unknown) => x is RelicFragmentId,
  leader: has(LEADER_IDS) as (x: unknown) => x is LeaderId,
  leaderStatus: ((x: unknown) => typeof x === "string" && has(LEADER_IDS)(x.replace(/:(locked|exhausted)$/, ""))) as (x: unknown) => x is LeaderStatus,
  strategyCard: has(STRATEGY_CARD_IDS) as (x: unknown) => x is StrategyCardId,
  strategyCardNumber: ((x: unknown) => typeof x === "number" && (STRATEGY_CARD_NUMBERS as readonly number[]).includes(x)) as (x: unknown) => x is StrategyCardNumber,
  color: isColorName as (x: unknown) => x is ColorName,
  promissoryNote: ((x: unknown) => {
    if (typeof x !== "string") return false;
    if (isFactionPn(x)) return true;
    const m = COLOR_PN.exec(x);
    return !!m && isColorName(m[1]);
  }) as (x: unknown) => x is PromissoryNoteId,
  phase: has(PHASES) as (x: unknown) => x is Phase,
};

/** Display name of a promissory note id ("red_sftt" → "Support for the Throne"); the id itself when unknown. */
export function promissoryNoteName(id: string): string {
  const names = PROMISSORY_NOTE_NAMES as Record<string, string>;
  if (names[id]) return names[id];
  const m = COLOR_PN.exec(id);
  return (m && names[m[2]]) || id;
}

/** Display name of any id in one of the families above (unknown ids come back unchanged). */
export function idName(id: string): string {
  for (const names of [FACTION_NAMES, TECH_NAMES, PLANET_NAMES, ACTION_CARD_NAMES, AGENDA_NAMES, PUBLIC_OBJECTIVE_NAMES, SECRET_OBJECTIVE_NAMES, RELIC_NAMES, EXPLORE_CARD_NAMES, LEADER_NAMES, STRATEGY_CARD_NAMES, UNIT_NAMES] as Record<string, string>[]) {
    const n = names[id];
    if (n) return n;
  }
  const base = id.replace(/:(locked|exhausted)$/, "");
  if (base !== id) return idName(base);
  return promissoryNoteName(id);
}
